vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
void main() {
  vec2 p = v_uv * 6.0;
  float field = sin(p.x + sin(p.y + u_progress * TAU)) + cos(p.y - u_progress * TAU);
  vec4 c = sourceAt(v_uv + vec2(sin(field), cos(field)) * u_amount * 0.025);
  vec3 tint = 0.5 + 0.5 * cos(field + vec3(0.0, 2.0, 4.0) + u_progress * TAU);
  c.rgb = mix(c.rgb, tint * c.a, u_amount * 0.5);
  fragColor = c;
}

uniform int u_axis;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
void main() {
  vec2 uv = v_uv;
  if (u_axis == 0) uv.x = abs(uv.x - 0.5) * 2.0;
  else uv.y = abs(uv.y - 0.5) * 2.0;
  fragColor = sourceAt(uv);
}

uniform float u_blockSize;
void main() {
  float size = u_blockSize * min(u_resolution.x, u_resolution.y);
  vec2 cells = u_resolution / size;
  vec2 uv = (floor(v_uv * cells) + 0.5) / cells;
  fragColor = texture(u_source, uv);
}

uniform float u_levels;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
void main() {
  vec4 c = sourceAt(v_uv);
  vec3 straight = c.a > 0.0 ? c.rgb / c.a : vec3(0.0);
  fragColor = vec4(floor(straight * (u_levels - 1.0) + 0.5) / (u_levels - 1.0) * c.a, c.a);
}

uniform float u_amount;
const float TAU = 6.28318530718;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
uint hash(uint x) { x ^= x >> 16; x *= 2146121005u; x ^= x >> 15; x *= 2221713035u; return x ^ (x >> 16); }
float randomValue(vec2 p) { return float(hash(uint(p.x) + hash(uint(p.y) + uint(u_seed) * 31u + 17u)) >> 8) / 16777216.0; }
void main() {
  vec2 uv = v_uv * 16.0;
  float column = floor(uv.x), offset = randomValue(vec2(column, 0.0));
  vec2 cell = vec2(fract(uv.x + sin(TAU * u_progress + column) * 0.15), fract(uv.y + u_progress * 4.0 + offset));
  float flake = 1.0 - smoothstep(0.05, 0.13, length(cell - 0.5));
  vec4 c = sourceAt(v_uv);
  c.rgb = mix(c.rgb, vec3(c.a), flake * u_amount);
  fragColor = c;
}

uniform float u_amount;
const float TAU = 6.28318530718;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
uint hash(uint x) { x ^= x >> 16; x *= 2146121005u; x ^= x >> 15; x *= 2221713035u; return x ^ (x >> 16); }
float randomValue(vec2 p) { return float(hash(uint(p.x) + hash(uint(p.y) + uint(u_seed) * 31u + 17u)) >> 8) / 16777216.0; }
void main() {
  vec2 cell = floor(v_uv * 16.0), p = fract(v_uv * 16.0) - 0.5;
  float r = randomValue(cell);
  float star = exp(-abs(p.x) * 24.0) * exp(-abs(p.y) * 5.0) + exp(-abs(p.y) * 24.0) * exp(-abs(p.x) * 5.0);
  float light = step(0.75, r) * pow(0.5 + 0.5 * sin(TAU * (u_progress + r)), 4.0) * star * u_amount;
  vec4 c = sourceAt(v_uv);
  c.rgb = mix(c.rgb, vec3(c.a), clamp(light, 0.0, 1.0));
  fragColor = c;
}

uniform float u_amount;
const float TAU = 6.28318530718;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
void main() {
  vec2 p = v_uv - 0.5;
  vec2 uv = v_uv + sin(p.yx * 20.0 + u_progress * TAU) * u_amount * 0.025;
  vec4 c = sourceAt(uv);
  vec3 tint = 0.5 + 0.5 * cos(TAU * (length(p) * 3.0 - u_progress) + vec3(0.0, 2.1, 4.2));
  c.rgb = mix(c.rgb, tint * c.a, u_amount * 0.6);
  fragColor = c;
}

uniform float u_amount;
const float TAU = 6.28318530718;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
void main() {
  vec4 c = sourceAt(v_uv);
  float scan = 0.75 + 0.25 * sin(v_uv.y * 128.0 * TAU);
  vec3 mask = 0.65 + 0.35 * cos(vec3(0.0, 2.1, 4.2) + v_uv.x * 128.0 * TAU);
  float band = 0.85 + 0.15 * cos(TAU * (v_uv.y - u_progress));
  c.rgb *= mix(vec3(1.0), mask * scan * band, u_amount);
  fragColor = c;
}
